const slug = (name) => name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const firstSentence = (t) => { const m = (t || "").match(/^.*?[.!?](?=\s|$)/); return m ? m[0] : t; };

const mapItems = allItems
  .filter((it) => !MAP_EXCLUDE.includes(it.anchor) && typeof it.lat === "number" && typeof it.lng === "number")
  .map((it) => ({ name: it.name, slug: slug(it.name), category: it.anchor, where: it.where, blurb: firstSentence(it.description), lng: it.lng, lat: it.lat }));

